   139→async function generateWithFallback(parts, modelCandidates) {
   140→  let lastError = "";
   141→  const tried = new Set();
   142→
   143→  for (const candidate of modelCandidates) {
   144→    if (!candidate || tried.has(candidate)) continue;
   145→    tried.add(candidate);
   146→    const result = await tryGenerateContent(candidate, parts);
   147→    if (result.answer) return { answer: result.answer, lastError: "" };
   148→    lastError = result.error || lastError;
   149→  }
   150→
   151→  const discoveredModels = await fetchGenerateSupportedModels();
   152→  for (const model of discoveredModels) {
   153→    if (tried.has(model)) continue;
   154→    const result = await tryGenerateContent(model, parts);
   155→    if (result.answer) return { answer: result.answer, lastError: "" };
   156→    lastError = result.error || lastError;
   157→  }
   158→
   159→  return { answer: "", lastError };
   160→}
   161→
   162→async function tryGenerateContent(model, parts) {
   163→  try {
   164→    const endpoint = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${encodeURIComponent(
   165→      GEMINI_API_KEY
   166→    )}`;
   167→
   168→    const response = await fetch(endpoint, {
   169→      method: "POST",
   170→      headers: { "Content-Type": "application/json" },
   171→      body: JSON.stringify({
   172→        contents: [{ parts }],
   173→        generationConfig: {
   174→          temperature: 0.2,
   175→          topP: 0.9,
   176→          topK: 32,
   177→          maxOutputTokens: 512,
   178→        },
   179→      }),
   180→    });
   181→
   182→    if (!response.ok) {
   183→      const raw = await response.text();
   184→      return { answer: "", error: `Model ${model} failed: ${raw}` };
   185→    }
   186→
   187→    const data = await response.json();
   188→    const answer = data?.candidates?.[0]?.content?.parts?.[0]?.text || "";
   189→    return { answer, error: "" };
   190→  } catch (error) {
   191→    return { answer: "", error: `Model ${model} request error: ${error.message}` };
   192→  }
   193→}
