   195→function cleanAssistantAnswer(answer) {
   196→  const text = String(answer || "").trim();
   197→  const lines = text.split("\n");
   198→  const cleaned = lines.filter((line, idx) => {
   199→    if (idx > 2) return true;
   200→    return !/^\s*(namaste|hello|hi|main chintak|i am chintak)/i.test(line.trim());
   201→  });
   202→  return cleaned.join("\n").trim() || text;
   203→}
   204→
   205→function parseDiseaseAnswer(text) {
   206→  const parsed = parseJsonAnswer(text);
   207→  if (Object.keys(parsed).length > 0) return parsed;
   208→
   209→  const clean = String(text || "").trim();
   210→  const firstSentence = clean.split(/\n|\./).map((s) => s.trim()).filter(Boolean)[0] || "";
   211→  return {
   212→    disease: firstSentence.slice(0, 80) || "Uncertain",
   213→    confidence: /high confidence|very likely/i.test(clean)
   214→      ? "High"
   215→      : /likely|moderate/i.test(clean)
   216→      ? "Medium"
   217→      : "Low",
   218→    explanation: clean || "Unable to reliably detect from image.",
   219→    recommendation: "Upload a close, well-lit image focused on the affected area.",
   220→  };
   221→}
   222→
   223→function sanitizeDiseaseText(value) {
   224→  return String(value || "")
   225→    .replace(/```json/gi, "")
   226→    .replace(/```/g, "")
   227→    .replace(/^[\s"'`{}[\]:,.-]+|[\s"'`{}[\]:,.-]+$/g, "")
   228→    .trim();
   229→}
   230→
   231→function normalizeCandidates(candidates) {
   232→  if (!Array.isArray(candidates)) return [];
   233→  return candidates
   234→    .map((item) => ({
   235→      name: sanitizeDiseaseText(item?.name),
   236→      confidence: sanitizeDiseaseText(item?.confidence),
   237→    }))
   238→    .filter((item) => item.name)
   239→    .slice(0, 3);
   240→}
