   242→async function fetchGenerateSupportedModels() {
   243→  try {
   244→    const endpoint = `https://generativelanguage.googleapis.com/v1beta/models?key=${encodeURIComponent(
   245→      GEMINI_API_KEY
   246→    )}`;
   247→    const response = await fetch(endpoint);
   248→    if (!response.ok) return [];
   249→    const data = await response.json();
   250→    const models = (data?.models || [])
   251→      .filter((m) => Array.isArray(m.supportedGenerationMethods) && m.supportedGenerationMethods.includes("generateContent"))
   252→      .map((m) => String(m.name || "").replace("models/", ""))
   253→      .filter(Boolean);
   254→    return models;
   255→  } catch {
   256→    return [];
   257→  }
   258→}
   259→
   260→function parseJsonAnswer(text) {
   261→  try {
   262→    const source = String(text || "").trim();
   263→    const deFenced = source
   264→      .replace(/^```json/i, "")
   265→      .replace(/^```/i, "")
   266→      .replace(/```$/i, "")
   267→      .trim();
   268→    try {
   269→      return JSON.parse(deFenced);
   270→    } catch {
   271→      const start = deFenced.indexOf("{");
   272→      const end = deFenced.lastIndexOf("}");
   273→      if (start !== -1 && end !== -1 && end > start) {
   274→        const maybeJson = deFenced.slice(start, end + 1);
   275→        return JSON.parse(maybeJson);
   276→      }
   277→    }
   278→    return {};
   279→  } catch {
   280→    return {};
   281→  }
   282→}
