     7→  { name: "Cotton", n: 55, p: 30, k: 60, reason: "Needs higher potassium for boll development." },
     8→  { name: "Pigeon Pea", n: 40, p: 30, k: 30, reason: "Legume with moderate nutrient requirements." },
     9→  { name: "Sugarcane", n: 90, p: 40, k: 55, reason: "Heavy feeder crop with higher nutrient demand." },
    10→];
    11→
    12→function predictCrops(n, p, k, topN = 3) {
    13→  const predictions = cropProfiles
    14→    .map((crop) => {
    15→      const distance = Math.abs(crop.n - n) + Math.abs(crop.p - p) + Math.abs(crop.k - k);
    16→      const confidence = Math.max(5, Math.min(99, 100 - Math.round(distance)));
    17→      return {
    18→        crop: crop.name,
    19→        confidence,
    20→        reason: crop.reason,
    21→        targetNPK: { n: crop.n, p: crop.p, k: crop.k },
    22→      };
    23→    })
    24→    .sort((a, b) => b.confidence - a.confidence)
    25→    .slice(0, topN);
    26→
    27→  return predictions;
    28→}
    29→
    30→module.exports = { predictCrops };
